def most_common_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    if not s:  # Handle empty string case
        return None

    best_char = s[0]
    best_count = counts[s[0]]

    for ch, count in counts.items():
        if count > best_count:
            best_count = count
            best_char = ch
        elif count == best_count:
            # If counts are equal, choose the character that appears earlier in the string
            if s.index(ch) < s.index(best_char):
                best_char = ch

    return best_char
```

